package com.roughpath.qa;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import java.util.concurrent.*;import java.lang.reflect.*;
/** Same-certificate instrumentation: verifies real WebView Worker/asset loading, no orders. */
public class WorkerCheck extends Instrumentation {
 private WebView web;
 public void onCreate(Bundle args){super.onCreate(args);start();}
 private String js(String script)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] out={""};runOnMainSync(()->web.evaluateJavascript(script,value->{out[0]=value;done.countDown();}));if(!done.await(8,TimeUnit.SECONDS))throw new Exception("WebView callback timed out");return out[0];}
 public void onStart(){Bundle result=new Bundle();try{Intent intent=new Intent();intent.setClassName("com.roughpath.alpha","com.roughpath.alpha.MainActivity");intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity activity=startActivitySync(intent);Field field=activity.getClass().getDeclaredField("web");field.setAccessible(true);web=(WebView)field.get(activity);boolean ready=false;for(int i=0;i<30;i++){if(js("typeof Rough==='object' && typeof researchState==='object'").equals("true")){ready=true;break;}Thread.sleep(500);}if(!ready)throw new Exception("Research page not initialized");js("window.__workerQA=null;var qaw=new Worker('optimizer.js');qaw.onerror=function(e){window.__workerQA={error:e.message};};qaw.onmessage=function(e){if(e.data.kind==='result'||e.data.kind==='error'){window.__workerQA=e.data;qaw.terminate();}};qaw.postMessage({rows:Array.from({length:1000},function(_,i){var p=100+5*Math.sin(i/20);return {t:1600000000000+i*60000,o:p,h:p+.1,l:p-.1,c:p};}),grid:{window:[16,32],threshold:[.4],noise:[.05],areaWeight:[1],smooth:[.1,.25],bandWindow:[16,32],bandMult:[1,2],projectionWindow:[8],projectionSteps:[6,12],projectionWeight:[.5]},costs:{balance:1000,leverage:5}});true;");String state="";boolean complete=false;for(int i=0;i<60;i++){state=js("window.__workerQA ? JSON.stringify({kind:window.__workerQA.kind,samples:window.__workerQA.samples,engineVersion:window.__workerQA.engineVersion,bandMult:window.__workerQA.best&&window.__workerQA.best.params.bandMult,projectionSteps:window.__workerQA.best&&window.__workerQA.best.params.projectionSteps,error:window.__workerQA.error||window.__workerQA.message}) : ''");if(state.contains("result")&&state.contains("1000")&&state.contains("1.1.0")&&state.contains("bandMult")&&state.contains("projectionSteps")){complete=true;break;}if(state.contains("error"))throw new Exception(state);Thread.sleep(500);}if(!complete)throw new Exception("Real Android Worker failed: "+state);result.putString("stream","OK (1 test)\nReal Android WebView worker: 1000 samples, channel/projection grid, v1.1 engine, results and bundled asset loader verified.\n");finish(Activity.RESULT_OK,result);}catch(Exception e){result.putString("stream","FAIL: "+e.toString()+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
